        const metrics = getPrototypeTimelineMetricsFromCanvas(canvas, settings || getSettings());
        const canvasHeight = Number(metrics?.canvasHeight || 0);
        const nowMinutesRaw = getDateMinutesOfDay(targetDate);
        if (!Number.isFinite(canvasHeight) || canvasHeight <= 0 || !Number.isFinite(nowMinutesRaw)) return false;
        const startMinutes = Number(guard?.startMinutes);
        const endMinutes = Number(guard?.endMinutes);
