    function getTimeAxisLabelColor() {
        const mixed = 'color-mix(in srgb, var(--tm-text-color) 72%, var(--tm-secondary-text) 28%)';
        try {
            const css = globalThis.CSS;
            if (css && typeof css.supports === 'function' && css.supports('color', 'color-mix(in srgb, #000 72%, #fff 28%)')) return mixed;
        } catch (e) {}
        return 'var(--tm-secondary-text, #8a8a8a)';
    }

    function normalizeTimeGridHourAxisTicks(rootEl) {
        if (!(rootEl instanceof HTMLElement)) return false;
        let changed = false;
        const parseDataTime = (node) => {
            const raw = String(node?.getAttribute?.('data-time') || '').trim();
            const m = raw.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
            if (!m) return null;
            return { hour: Number(m[1]), minute: Number(m[2]) };
        };
        const setClass = (node, className, enabled) => {
            if (!(node instanceof HTMLElement)) return;
            const has = node.classList.contains(className);
            if (enabled && !has) {
                node.classList.add(className);
                changed = true;
            } else if (!enabled && has) {
                node.classList.remove(className);
                changed = true;
            }
        };
        const findLabelFrame = (label) => {
            if (!(label instanceof HTMLElement)) return null;
            return label.querySelector(':scope > .tm-legacy-calendar-timegrid-slot-label-frame')
                || label.querySelector('.tm-legacy-calendar-timegrid-slot-label-frame');
        };
        const findLabelCushion = (label, frame) => {
            if (frame instanceof HTMLElement && frame.classList.contains('tm-calendar-legacy-timegrid-slot-label-cushion')) return frame;
            return frame?.querySelector?.(':scope > .tm-legacy-calendar-timegrid-slot-label-cushion')
                || frame?.querySelector?.('.tm-legacy-calendar-timegrid-slot-label-cushion')
                || label?.querySelector?.(':scope > .tm-legacy-calendar-timegrid-slot-label-cushion')
                || label?.querySelector?.('.tm-legacy-calendar-timegrid-slot-label-cushion')
                || null;
        };
        const labels = Array.from(rootEl.querySelectorAll('.tm-legacy-calendar-timegrid-slot-label[data-time]'));
        for (const label of labels) {
            if (!(label instanceof HTMLElement)) continue;
            const time = parseDataTime(label);
            if (!time) continue;
            const isHour = time.minute === 0;
            const isHalfHour = time.minute === 30;
            if (!isHour && !isHalfHour) continue;
            setClass(label, 'tm-calendar-legacy-timegrid-slot-minor', isHalfHour);
            setClass(label, 'tm-calendar-legacy-scrollgrid-shrink', isHour);
            if (isHour) {
                let frame = findLabelFrame(label);
                if (!(frame instanceof HTMLElement)) {
                    frame = document.createElement('div');
                    frame.className = 'tm-calendar-legacy-timegrid-slot-label-frame tm-calendar-legacy-scrollgrid-shrink-frame';
                    label.replaceChildren(frame);
                    changed = true;
                }
                let cushion = findLabelCushion(label, frame);
                if (!(cushion instanceof HTMLElement)) {
                    cushion = document.createElement('div');
                    cushion.className = 'tm-calendar-legacy-timegrid-slot-label-cushion tm-calendar-legacy-scrollgrid-shrink-cushion';
                    frame.replaceChildren(cushion);
                    changed = true;
                }
                const text = String(time.hour);
                if (String(cushion.textContent || '') !== text) {
                    cushion.textContent = text;
                    changed = true;
                }
            } else {
                const frame = findLabelFrame(label);
                const cushion = findLabelCushion(label, frame);
                const textNode = cushion instanceof HTMLElement ? cushion : label;
                if (textNode.textContent) {
                    textNode.textContent = '';
                    changed = true;
                }
            }
        }
        rootEl.querySelectorAll('.tm-legacy-calendar-timegrid-slot-lane[data-time]').forEach((lane) => {
            if (!(lane instanceof HTMLElement)) return;
            const time = parseDataTime(lane);
            if (!time) return;
            if (time.minute === 0) setClass(lane, 'tm-calendar-legacy-timegrid-slot-minor', false);
            else if (time.minute === 30) setClass(lane, 'tm-calendar-legacy-timegrid-slot-minor', true);
        });
        return changed;
    }

