            const col = findColByX(xp);
            const dateStr = String(col?.getAttribute?.('data-date') || '').trim();
            if (!dateStr) return null;
            const slotsWrap = root.querySelector('.tm-legacy-calendar-timegrid-slots');
            const slotsTable = slotsWrap?.querySelector?.('table');
            const scroller = root.querySelector('.tm-legacy-calendar-timegrid-body .tm-legacy-calendar-scroller, .tm-legacy-calendar-timegrid-body .tm-legacy-calendar-scroller-liquid-absolute, .tm-legacy-calendar-scroller');
            if (!(slotsWrap instanceof HTMLElement) || !(slotsTable instanceof HTMLElement)) return null;
            const wrapRect = slotsWrap.getBoundingClientRect();
