                // its first cell so its width can span all covered days and
                // the title is not clipped into one-day fragments.
                const spanMarkup = daySpanSegments
                    .filter((segment) => {
                        if (Number(segment?.renderIndex) !== Number(segment?.segmentStartIndex)) return false;
                        const blockedDays = segment?.eventApi?.extendedProps?.__tmScheduledTaskDayKeys;
                        return !(Array.isArray(blockedDays) && blockedDays.includes(key));
                    })
                    .map((segment) => protoSpanMarkup(segment.eventApi, date, segment, 'dayGridMonth'))
                    .join('');
                const reserveLanes = Number(spanLayout.reserves.get(index) || 0);
                const spanReserveHeight = Math.max(22, reserveLanes * 25 - 3);
                const spanReserve = reserveLanes > 0
                    ? `<span class="tm-proto-month-span-reserve" style="height:${spanReserveHeight}px !important" aria-hidden="true"></span>`
                    : '';
